custom.expression:
let q = p * shape_scale;
let sway = 0.04 * sin(t * 0.3 * drift_speed);
let g0 = vec2<f32>(q.x * 5.0 + t * 0.08 * drift_speed, q.y * 5.0 + sway * 5.0);
let c0 = floor(g0);
let f0 = fract(g0) - 0.5;
let s0 = hash(c0 + vec2<f32>(1.0, 7.0));
let r0 = rotate(f0, t * spin * (0.3 + s0) + s0 * 6.28);
let m0 = 0.5 + 0.5 * sin(t * drift_speed * (0.4 + s0) + s0 * 9.0);
let oval0 = sd_circle(vec2<f32>(r0.x * 1.8, r0.y), 0.12);
let wave0 = abs(r0.y - 0.08 * cos(r0.x * 14.0 + t * drift_speed)) - 0.01;
let dot0 = min(sd_circle(r0 - vec2<f32>(0.12, 0.0), 0.03), sd_segment(r0, vec2<f32>(-0.2, 0.0), vec2<f32>(0.05, 0.0)));
let corner0 = min(sd_segment(r0, vec2<f32>(-0.15, -0.15), vec2<f32>(-0.15, 0.15)), sd_segment(r0, vec2<f32>(-0.15, -0.15), vec2<f32>(0.15, -0.15))) - 0.005;
var d0 = mix(oval0, wave0, m0);
if (s0 > 0.5) {
    d0 = mix(dot0, corner0, m0);
}
let ink0 = fill(d0) * 0.4 + stroke(d0, 0.008);
let col0 = mix(c4, c2, s0) * ink0 * 0.5;

let g1 = vec2<f32>(q.x * 3.5 + t * 0.18 * drift_speed, q.y * 3.5 - sway * 3.0);
let c1g = floor(g1);
let f1 = fract(g1) - 0.5;
let s1 = hash(c1g + vec2<f32>(3.0, 2.0));
let r1 = rotate(f1, -t * spin * (0.5 + s1) + s1 * 6.28);
let m1 = 0.5 + 0.5 * cos(t * drift_speed * (0.6 + s1) + s1 * 5.0);
let plus1 = min(sd_box(r1, vec2<f32>(0.16, 0.025)), sd_box(r1, vec2<f32>(0.025, 0.16)));
let oval1 = sd_circle(vec2<f32>(r1.x * 1.8, r1.y), 0.12);
let wave1 = abs(r1.y - 0.08 * cos(r1.x * 14.0 - t * drift_speed)) - 0.01;
let dot1 = min(sd_circle(r1 - vec2<f32>(0.12, 0.0), 0.03), sd_segment(r1, vec2<f32>(-0.2, 0.0), vec2<f32>(0.05, 0.0)));
var d1 = mix(plus1, oval1, m1);
if (s1 > 0.5) {
    d1 = mix(wave1, dot1, m1);
}
let ink1 = fill(d1) * 0.4 + stroke(d1, 0.009);
let col1 = mix(c2, c5, s1) * ink1 * 0.8;

let g2 = vec2<f32>(q.x * 2.2 + t * 0.3 * drift_speed, q.y * 2.2 + sway);
let c2g = floor(g2);
let f2 = fract(g2) - 0.5;
let s2 = hash(c2g + vec2<f32>(5.0, 11.0));
let r2 = rotate(f2, t * spin * 0.8 * (0.5 + s2) + s2 * 6.28);
let m2 = 0.5 + 0.5 * sin(t * drift_speed * (0.5 + s2) + s2 * 4.0);
let corner2 = min(sd_segment(r2, vec2<f32>(-0.18, -0.18), vec2<f32>(-0.18, 0.18)), sd_segment(r2, vec2<f32>(-0.18, -0.18), vec2<f32>(0.18, -0.18))) - 0.006;
let oval2 = sd_circle(vec2<f32>(r2.x * 1.6, r2.y), 0.15);
var d2 = mix(oval2, corner2, m2);
let ink2 = fill(d2) * 0.35 + stroke(d2, 0.01);
let col2 = mix(c1, c3, s2) * ink2 * 1.1;

let light = col0 + col1 + col2;
let wash = mix(bg, c4 * 0.22, smoothstep(-0.5, 0.5, p.y));
let color = wash + tonemap(light);
return mix(bg, clamp(color, vec3<f32>(0.0), vec3<f32>(1.0)), strength);
